function s(t){if(!t)return null;if(t instanceof Date)return isNaN(t.getTime())?null:t;try{const n=typeof t=="string"?t.trim().replace(" ","T"):t,e=new Date(n);return isNaN(e.getTime())?null:e}catch{return null}}function a(t){const n=s(t);if(!n)return 0;const e=Math.floor((Date.now()-n.getTime())/6e4);return Math.max(0,isNaN(e)?0:e)}function f(t){if(!t)return{text:"0m",isLong:!1,minutes:0};const n=s(t);if(!n)return{text:"0m",isLong:!1,minutes:0};const e=Math.max(0,Math.floor((Date.now()-n.getTime())/6e4));if(isNaN(e))return{text:"0m",isLong:!1,minutes:0};const i=Math.floor(e/60),r=e%60,o=i>=24;return i===0?{text:`${r}m`,isLong:!1,minutes:e}:{text:`${i}h ${r}m`,isLong:o,minutes:e}}function m(t,n="---",e={hour:"2-digit",minute:"2-digit"}){const i=s(t);if(!i)return n;try{return i.toLocaleTimeString("es-GT",e)}catch{return n}}export{s as a,a as b,f,m as s};
